"""OFFLINE proposal: one test-only source delta; review before any application.

Không đổi ZIP/base receipt, production source hoặc chạy tests/models/install.
Partial attempt giữ nguyên, không rollback/retry tự động.
"""
import argparse
import base64
import copy
import hashlib
import json
import math
import os
from pathlib import Path,PurePosixPath
import platform
import stat
import time
import traceback

ROOT=Path('/content/KLTN_GPU08_20261108_01')
DIRECTORY=ROOT/'source-delta01'
BASE_RECEIPT=ROOT/'gpu09-worker-kit-materialization-01.json'
BASE_SHA='debb7590e8fd1247bcbdf7a479c2ea204b7d8625414c989b0a4bab5c1e831c3b'
BASE_ZIP=ROOT/'source-kit-transfer01/exact-linux-cpu-source-kit.zip'
ARCHIVE_SHA='b6707cfd0139898a22dd04db9095d01622c1df9b7061f05f8579ecb4ab30d233'
TARGET='tests/akt/test_graph_prototype.py'
OLD_SHA='5e2aae220d1b862c337951182efab417a3ed81dd5eb6899f84af710a3cfd76ae'
NEW_SHA='7a198d79b11b0c2e18af8532f26658e7119a2e352299d4bba66f859c16082f04'
OLD_BYTES=16086
NEW_BYTES=17214
NEW_RECEIPT=ROOT/'gpu09-worker-kit-materialization-02.json'
PAYLOAD_B64=''
CAP_SECONDS=30
LOADER_SOURCE_SHA='6aff88a7abc9620d6372ee934391d2079bccd253330e7a1e4f0ddcaa436b41b2'
LOADER_SHA='27550ccd07c1131971c4381f024c0f3795dba3d32b7f9fb4eea4ababd8bfe9e8'
LOADER_BLOB='9fafe965e0b442242125250f37dc8c3f8a145edf'
sha=lambda raw:hashlib.sha256(raw).hexdigest()


def read(path,cap=4*1024**2):
    if not path.is_absolute() or not path.is_relative_to(ROOT):raise ValueError('outside owned root')
    for part in (path,*path.parents):
        if part.is_symlink():raise ValueError('link forbidden')
        if part==ROOT:break
    if not stat.S_ISREG(path.stat().st_mode):raise ValueError('regular file required')
    with path.open('rb') as stream:raw=stream.read(cap+1)
    if len(raw)>cap:raise ValueError('read cap')
    return raw


def validate_manifest(base,payload):
    if (base.get('status')!='MATERIALIZED_SOURCE_ONLY_NO_EXECUTION' or base.get('archive_sha256')!=ARCHIVE_SHA
            or len(base.get('manifest',{}).get('files',{}))!=161):raise ValueError('exact base161 materialization required')
    if base['manifest']['files'].get(TARGET)!={'bytes':OLD_BYTES,'sha256':OLD_SHA}:raise ValueError('base target entry mismatch')
    if len(payload)!=NEW_BYTES or sha(payload)!=NEW_SHA:raise ValueError('reviewed new test bytes required')
    manifest=copy.deepcopy(base['manifest'])
    manifest['kind']='EXACT_BASE_SOURCE_KIT_PLUS_ONE_TEST_ONLY_DELTA'
    manifest['scope']='materialized source inventory; base ZIP unchanged and does not contain delta; no Gate acceptance'
    manifest['files'][TARGET]={'bytes':NEW_BYTES,'sha256':NEW_SHA}
    return manifest


def verify_loader_receipt(receipt):
    if (receipt.get('status')!='MATERIALIZED_TRANSFERRED_PINNED_LOADER_SOURCE_ONLY'
            or receipt.get('source_sha256')!=LOADER_SOURCE_SHA
            or receipt.get('source_origin')!='LOCAL_PINNED_GIT_BLOB_TRANSFER'
            or receipt.get('cleanup',{}).get('accepted') is not True
            or receipt.get('audit',{}).get('source_origin')!='LOCAL_PINNED_GIT_BLOB_TRANSFER'
            or receipt.get('audit',{}).get('loader')!={'path':'load_data.py','sha256':LOADER_SHA,'git_blob_id':LOADER_BLOB,'bytes':6428}):
        raise ValueError('loader remediation must be accepted BEFORE source delta')


def loader_relative_path(value):
    path=PurePosixPath(value)
    if (path.is_absolute() or '..' in path.parts or '\\' in value or ':' in value or path.as_posix()!=value
            or len(path.parts)!=2 or not path.parts[0].startswith('upstream-loader-transfer') or path.name!='result.json'):
        raise ValueError('explicit ROOT-relative loader remediation result path required')
    return path.as_posix()


def inventory(files):
    rows={}
    for name,entry in files.items():
        relative=PurePosixPath(name)
        if relative.is_absolute() or '..' in relative.parts or '\\' in name or ':' in name or relative.as_posix()!=name:
            raise ValueError('manifest path invalid')
        raw=read(ROOT/name)
        if len(raw)!=entry['bytes'] or sha(raw)!=entry['sha256']:raise ValueError('source inventory mismatch: '+name)
        rows[name]={'bytes':len(raw),'sha256':sha(raw)}
    return rows


def exclusive(path,raw):
    with path.open('xb') as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())


def encoded(value):return (json.dumps(value,indent=2,allow_nan=False)+'\n').encode()

def within_budget(start,wall):
    if not all(math.isfinite(v) and 0<=v<=CAP_SECONDS for v in (time.monotonic()-start,time.time()-wall)):
        raise TimeoutError('source-only30s bound')


def main(argv=None):
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--expected-source-sha256',required=True)
    parser.add_argument('--loader-remediation-sha256',required=True)
    parser.add_argument('--loader-remediation-path',required=True)
    parser.add_argument('--approval-reference',required=True)
    args=parser.parse_args(argv);start=time.monotonic();wall=time.time()
    if not (os.name=='posix' and platform.system()=='Linux' and ROOT.is_dir() and ROOT.resolve()==ROOT
            and ROOT.stat().st_uid==os.getuid() and not DIRECTORY.exists() and not DIRECTORY.is_symlink()
            and not NEW_RECEIPT.exists() and not NEW_RECEIPT.is_symlink()):raise ValueError('owned Linux root/exclusive delta required')
    if os.environ.get('COLAB_GPU') not in (None,'','0') or os.environ.get('COLAB_TPU_ADDR') or list(Path('/dev').glob('nvidia[0-9]*')):
        raise ValueError('CPU host only')
    source=Path(__file__).absolute()
    if source!=ROOT/'apply_source_delta01.py' or sha(read(source))!=args.expected_source_sha256 or not args.approval_reference.strip():
        raise ValueError('reviewed source/approval required')
    base_raw=read(BASE_RECEIPT);archive=read(BASE_ZIP)
    if sha(base_raw)!=BASE_SHA or sha(archive)!=ARCHIVE_SHA:raise ValueError('immutable base receipt/ZIP mismatch')
    loader_name=loader_relative_path(args.loader_remediation_path);loader_path=ROOT/loader_name
    loader_raw=read(loader_path)
    if sha(loader_raw)!=args.loader_remediation_sha256:raise ValueError('actual loader remediation SHA required')
    verify_loader_receipt(json.loads(loader_raw))
    if sha(read(ROOT/'artifacts/akt/dependencies/upstream/load_data.py'))!=LOADER_SHA:raise ValueError('actual loader source missing/drift')
    payload=base64.b64decode(PAYLOAD_B64,validate=True);base=json.loads(base_raw);manifest=validate_manifest(base,payload)
    before=inventory(base['manifest']['files']);old=read(ROOT/TARGET)
    if sha(old)!=OLD_SHA or len(old)!=OLD_BYTES:raise ValueError('old target mismatch')
    within_budget(start,wall)
    DIRECTORY.mkdir(exist_ok=False)
    result={'status':'FAILED_SOURCE_DELTA_RETAIN_PARTIAL','source_sha256':args.expected_source_sha256,
            'approval_reference':args.approval_reference,'target':TARGET,'base_archive_sha256':ARCHIVE_SHA,
            'base_materialization_sha256':BASE_SHA,'model_test_install_network_calls':0,'new_archive_created':False}
    try:
        exclusive(DIRECTORY/'test_graph_prototype.before.py',old)
        exclusive(DIRECTORY/'test_graph_prototype.after.py',payload)
        exclusive(DIRECTORY/'inventory_before.json',encoded(before))
        if sha(read(ROOT/TARGET))!=OLD_SHA:raise ValueError('target changed before replacement')
        temporary=DIRECTORY/'replacement.tmp';exclusive(temporary,payload)
        os.chmod(temporary,stat.S_IMODE((ROOT/TARGET).stat().st_mode))
        within_budget(start,wall)
        os.replace(temporary,ROOT/TARGET)
        after=inventory(manifest['files'])
        if [name for name in before if before[name]!=after[name]]!=[TARGET]:raise ValueError('must change exactly one test')
        exclusive(DIRECTORY/'inventory_after.json',encoded(after))
        if (sha(read(BASE_RECEIPT))!=BASE_SHA or sha(read(BASE_ZIP))!=ARCHIVE_SHA or sha(read(source))!=args.expected_source_sha256
                or sha(read(loader_path))!=args.loader_remediation_sha256
                or sha(read(ROOT/'artifacts/akt/dependencies/upstream/load_data.py'))!=LOADER_SHA):
            raise ValueError('immutable base/source drift')
        within_budget(start,wall)
        material={'status':'MATERIALIZED_SOURCE_DELTA_ONLY_NO_EXECUTION','base_archive_sha256':ARCHIVE_SHA,
            'base_materialization_receipt_sha256':BASE_SHA,'base_archive_contains_delta':False,'new_archive_created':False,
            'manifest':manifest,'source_sha256_after':{name:row['sha256'] for name,row in after.items()},
            'delta':{'target':TARGET,'old_sha256':OLD_SHA,'new_sha256':NEW_SHA,'old_bytes':OLD_BYTES,'new_bytes':NEW_BYTES,
                     'controller_source_sha256':args.expected_source_sha256,'backup_path':'source-delta01/test_graph_prototype.before.py',
                     'loader_remediation_sha256':args.loader_remediation_sha256,
                     'loader_remediation_path':loader_name,
                     'backup_sha256':sha(read(DIRECTORY/'test_graph_prototype.before.py')),
                     'inventory_before_sha256':sha(read(DIRECTORY/'inventory_before.json')),
                     'inventory_after_sha256':sha(read(DIRECTORY/'inventory_after.json'))},
            'source_delta_result_path':'source-delta01/result.json','installed_runtime_or_Gate_acceptance':False}
        material_raw=encoded(material);exclusive(NEW_RECEIPT,material_raw)
        result.update(status='ACCEPTED_TEST_ONLY_SOURCE_DELTA_NO_EXECUTION',new_materialization_sha256=sha(material_raw),
                      new_materialization_path=str(NEW_RECEIPT),changed_paths=[TARGET],inventory_file_count=161,
                      old_backup_sha256=OLD_SHA,new_target_sha256=NEW_SHA,other160files_unchanged=True)
    except Exception as exc:
        result.update(error_type=type(exc).__name__,error=str(exc))
        exclusive(DIRECTORY/'failure.log',traceback.format_exc().encode())
    finally:
        result.update(elapsed_seconds=time.monotonic()-start,elapsed_wall_seconds=time.time()-wall,cap_seconds=CAP_SECONDS)
        if not all(math.isfinite(v) and 0<=v<=CAP_SECONDS for v in (result['elapsed_seconds'],result['elapsed_wall_seconds'])):
            result['status']='REJECTED_SOURCE_DELTA_ELAPSED_BOUND'
        exclusive(DIRECTORY/'result.json',encoded(result))
        print(json.dumps({'status':result['status'],'result_sha256':sha(read(DIRECTORY/'result.json')),
                          'new_materialization_sha256':result.get('new_materialization_sha256'),'source_changes':result.get('changed_paths')}))
    return 0 if result['status']=='ACCEPTED_TEST_ONLY_SOURCE_DELTA_NO_EXECUTION' else 1


if __name__=='__main__':raise SystemExit(main())
